func (m RerankResponseMultiError) AllErrors() []error { return m }

// RerankResponseValidationError is the validation error returned by
// RerankResponse.Validate if the designated constraints aren't met.
type RerankResponseValidationError struct {
	field  string
	reason string
	cause  error
	key    bool
}

// Field function returns field value.
func (e RerankResponseValidationError) Field() string { return e.field }

// Reason function returns reason value.
func (e RerankResponseValidationError) Reason() string { return e.reason }

// Cause function returns cause value.
func (e RerankResponseValidationError) Cause() error { return e.cause }

// Key function returns key value.
func (e RerankResponseValidationError) Key() bool { return e.key }

// ErrorName returns error name.
func (e RerankResponseValidationError) ErrorName() string { return "RerankResponseValidationError" }

// Error satisfies the builtin error interface
func (e RerankResponseValidationError) Error() string {
	cause := ""
	if e.cause != nil {
		cause = fmt.Sprintf(" | caused by: %v", e.cause)
	}

	key := ""
	if e.key {
		key = "key for "
	}

	return fmt.Sprintf(
		"invalid %sRerankResponse.%s: %s%s",
		key,
		e.field,
		e.reason,
		cause)
}

var _ error = RerankResponseValidationError{}

var _ interface {
	Field() string
	Reason() string
	Key() bool
	Cause() error
	ErrorName() string
} = RerankResponseValidationError{}
